import time

def retry_with_backoff(fn, max_attempts=3):
    """
    Call `fn` up to `max_attempts` times, retrying on any exception.
    If a call succeeds, its result is returned immediately.
    If all attempts fail, the last exception is re‑raised without an additional sleep.
    """
    for attempt in range(1, max_attempts + 1):
        try:
            return fn()
        except Exception as exc:
            if attempt == max_attempts:
                # Final attempt failed – re‑raise the exception without sleeping.
                raise
            # Exponential back‑off: sleep a little longer each retry.
            time.sleep(0.01 * attempt)
