import time

def retry_with_backoff(fn, max_attempts=3):
    """
    Call `fn` up to `max_attempts` times, retrying on any exception.
    If a call succeeds, its result is returned immediately.
    If all attempts fail, the last exception is re‑raised without an
    additional sleep after the final attempt.
    """
    for attempt in range(1, max_attempts + 1):
        try:
            return fn()
        except Exception as exc:
            # If this was the last allowed attempt, re‑raise the exception
            if attempt == max_attempts:
                raise
            # Otherwise wait a bit before retrying
            time.sleep(0.01 * attempt)
